INSERT INTO `sms_templates` VALUES (1,'Fees reminder','Dear {parent}, this is a reminder that {pupil} ({class}) has an outstanding fees balance of {balance}. Kindly pay at the school office. Thank you. - {school}',NULL,'2026-10-10 07:11:35','2026-10-10 07:11:35'),(2,'PTA meeting','Dear {parent}, you are invited to the PTA meeting on [day, date] at [time] at the school. Your presence is important. - {school}',NULL,'2026-10-10 07:11:35','2026-10-10 07:11:35'),(3,'Vacation notice','Dear {parent}, school vacates on [date]. Terminal reports will be given out on that day. Next term begins on [date]. - {school}',NULL,'2026-10-10 07:11:35','2026-10-10 07:11:35'),(4,'Reopening reminder','Dear {parent}, school reopens on [date]. Please ensure {first_name} reports early with all items needed. - {school}',NULL,'2026-10-10 07:11:35','2026-10-10 07:11:35'),(5,'Exams timetable','Dear {parent}, end-of-term examinations start on [date]. Please help {first_name} prepare well. - {school}',NULL,'2026-10-10 07:11:35','2026-10-10 07:11:35'),(6,'Holiday / closure','Dear {parent}, please note that school will be closed on [date] for [reason]. Classes resume on [date]. - {school}',NULL,'2026-10-10 07:11:35','2026-10-10 07:11:35'),(7,'Staff meeting','Dear {name}, there will be a staff meeting on [day] at [time] in the staff common room. - {school}',NULL,'2026-10-10 07:11:35','2026-10-10 07:11:35');
/*!40000 ALTER TABLE `sms_templates` ENABLE KEYS */;
UNLOCK TABLES;

