--
-- Table structure for table `students`
--

DROP TABLE IF EXISTS `students`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `students` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `index_number` varchar(255) NOT NULL,
  `reference_number` varchar(7) DEFAULT NULL,
  `house_id` bigint(20) unsigned DEFAULT NULL,
  `boarding_status` enum('day','boarder') DEFAULT NULL,
  `full_name` varchar(255) NOT NULL,
  `date_of_birth` date DEFAULT NULL,
  `gender` enum('Male','Female','Other') NOT NULL,
  `programme_id` bigint(20) unsigned DEFAULT NULL,
  `level` smallint(5) unsigned DEFAULT NULL,
  `class_group_id` bigint(20) unsigned DEFAULT NULL,
  `status` enum('active','graduated','withdrawn') NOT NULL DEFAULT 'active',
  `graduation_year` smallint(5) unsigned DEFAULT NULL,
  `profile_photo` varchar(255) DEFAULT NULL,
  `emergency_contact_name` varchar(255) DEFAULT NULL,
  `emergency_contact_phone` varchar(255) DEFAULT NULL,
  `parent_email` varchar(255) DEFAULT NULL,
  `email` varchar(255) DEFAULT NULL,
  `profile_picture` varchar(255) DEFAULT NULL,
  `phone` varchar(255) DEFAULT NULL,
  `address` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `hometown` varchar(255) DEFAULT NULL,
  `gps_address` varchar(255) DEFAULT NULL,
  `emergency_contact_relationship` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `students_index_number_unique` (`index_number`),
  UNIQUE KEY `students_reference_number_unique` (`reference_number`),
  KEY `students_programme_id_foreign` (`programme_id`),
